SELECT a.tenant_id, a.principal_id AS entity_id, a.event_id || '|' || d.event_id AS evidence_ids FROM events a JOIN events d ON d.tenant_id=a.tenant_id AND d.domain='cloud-aws' AND d.phase=1 AND d.action='data_read' AND d.principal_id=a.runtime_id AND d.workload_id=a.workload_id AND d.ts-a.ts BETWEEN :min_order_gap AND 1800 WHERE a.phase=1 AND a.domain='cloud-aws' AND a.action='ai_job_created' AND d.is_sensitive=1 AND NOT EXISTS (SELECT 1 FROM events b WHERE b.phase=0 AND b.tenant_id=a.tenant_id AND b.principal_id=a.principal_id AND b.runtime_id=a.runtime_id);
